def grid(G,hi=None,lbl="מלפנים ↑",title=None,hc="#f5b83d"):
  f={"type":"plot","axes":False,"X":[-0.5,4.5],"Y":[-1.2,4.9],"eq":True,"w":520,"h":470,"pad":16,"segs":[],"txt":[]}
  if hi: f["poly"]=[{"p":[[c,3-r],[c+1,3-r],[c+1,4-r],[c,4-r]],"fill":hc,"op":.45} for r,c in hi]
  for i in range(5): f["segs"]+=[{"p":[i,0,i,4],"c":"#1d2a6b","w":3},{"p":[0,i,4,i],"c":"#1d2a6b","w":3}]
  for r in range(4):
    for c in range(4):
      if G[r][c] is not None: f["txt"].append({"x":c+0.5,"y":3.32-r,"t":str(G[r][c]),"fs":40,"c":"#1d2a6b" if G[r][c] else "#b6bccb"})
  f["txt"].append({"x":2,"y":-0.75,"t":lbl,"fs":26,"c":"#c8242f"})
  if title: f["txt"].append({"x":2,"y":4.35,"t":title,"fs":26,"c":"#16824f"})
  return f
def view(H,lbl,sides=("קדימה","אחורה"),add=None):
  f={"type":"plot","axes":False,"X":[-0.5,4.5],"Y":[-1.2,3.8],"eq":True,"w":520,"h":420,"pad":16,"segs":[{"p":[-0.3,0,4.3,0],"c":"#5a6278","w":3}],"poly":[]}
  for c,h in enumerate(H):
    for k in range(h): f["poly"].append({"p":[[c,k],[c+1,k],[c+1,k+1],[c,k+1]],"fill":"#2f55c8","op":.25,"st":"#1d2a6b"})
  for c,k in (add or []): f["poly"].append({"p":[[c,k],[c+1,k],[c+1,k+1],[c,k+1]],"fill":"#f5b83d","op":.8,"st":"#1d2a6b"})
  f["txt"]=[{"x":2,"y":-0.9,"t":lbl,"fs":26,"c":"#c8242f"},{"x":0.5,"y":-0.45,"t":sides[0],"fs":20,"c":"#5a6278"},{"x":3.5,"y":-0.45,"t":sides[1],"fs":20,"c":"#5a6278"}]
  return f
